export function $check_requirements() {
    let timer = -1;
    clearInterval(timer);
    let route = get_route('VUE_APP_INTEGRATED');
    $post(route, {}).then((response) => {
        populate_status(response.data.data.status);
        if (response.data.data.status.error) {
            // Disable the plugin if a requirement error exist
            document.getElementById("payplug_enable-0").click();
            document.getElementById("payplug_enable").classList.add("-disabled");
        } else {
            // Enable the plugin if a no requirement error exist
            document.getElementById("payplug_enable-1").click();
            document.getElementById("payplug_enable").classList.remove("-disabled");
        }

    }).catch(function (error) {
        console.log(error);

    }).finally(function () {
        store.settings.loading.status = false;
        if (!store.translations.status.error) {
            store.success_check = true;
            timer = setInterval(() => {
                store.success_check = false;
            }, 5000);
        }
    })

}

export async function $save() {

    store.data.action = 'payplug_save_data';
    store.settings.save.disabled = true;
    store.settings.loading.global = true;
    let response_data = null;

    let response = await new Promise((resolve) => {
        let route = get_route('VUE_APP_SAVE');
        $post(route, store.data)
            .then((response) => {
                resolve(response.data);
                response_data = response.data;
            })
            .catch(error => {
                // eslint-disable-next-line valid-typeof
                if (!(typeof error.response.data.data == null) && typeof error.response.data.data != "undefined") {
                    store.settings.save.data = error.response.data.data;

                } else {
                    store.settings.save.data = {
                        msg: "It's not possible to save the configurations",
                        class: "error",
                        title: "Save Configurations Fail",
                        close: "Close"
                    }
                }

                return false;

            }).finally(function () {
            store.settings.save.disabled = false;
            store.settings.loading.global = false;

            if (store.translations.payment_paylater instanceof PayplugPaylater) {
                validation_fields();
            }

            if (typeof response_data.send_telementry != 'undefined' && response_data.send_telementry) {
                send_telemetry();
            }
        });
    });

    store.settings.save.data = response.data;
}

export function send_telemetry() {
    let route = get_route('VUE_APP_TELEMETRY');
    let response = new Promise((resolve) => {
        $post(route)
            .then((response) => {
                resolve(response.data);
            })
            .catch((error) => {
                console.log(error);
            });
    });

    return response;
}

export function validation_fields() {
    //validate oney_threshold fields
    oney_threshold_validation();

    function oney_threshold_validation() {
        let min = parseInt(store.data.oney_min_amounts);
        let max = parseInt(store.data.oney_max_amounts);

        const min_threshold = document.getElementsByName('oney_min_amounts')[0];
        const max_threshold = document.getElementsByName('oney_max_amounts')[0];
        const default_min_threshold = parseInt(min_threshold.min);
        const default_max_threshold = parseInt(max_threshold.max);

        if (min < default_min_threshold || max > default_max_threshold || min > max) {
            min_threshold.value = default_min_threshold;
            max_threshold.value = default_max_threshold;
            min_threshold.focus();
            max_threshold.focus();

            store.data.oney_min_amounts = default_min_threshold;
            store.data.oney_max_amounts = default_max_threshold;
        }
    }

}

export function populate(data) {
    store.translations.header = typeof data.header !== "undefined" ? new PayplugHeader(data.header) : null;
    store.translations.login = typeof data.login !== "undefined" ? new PayplugLogin(data.login) : null;
    store.translations.oauth_login = typeof data.oauth_login !== "undefined" ? new PayplugOauthLogin(data.oauth_login) : null;
    store.translations.subscribe = typeof data.subscribe !== "undefined" ? new PayplugSubscribe(data.subscribe) : null;
    store.translations.logged = typeof data.logged !== "undefined" ? new PayplugLogged(data.logged, data.payplug_wooc_settings) : null;
    store.translations.payment_paylater = typeof data.payment_paylater !== "undefined" ? new PayplugPaylater(data.payment_paylater) : null;
    store.translations.payment_methods = typeof data.payment_methods !== "undefined" ? new PayplugPaymentMethods(data.payment_methods) : null;
    store.translations.status = typeof data.status !== "undefined" ? new PayplugStatus(data.status) : null;
    store.translations.debug = typeof data.status !== "undefined" ? new PayplugDebugMode(data.status) : null;
    store.translations.footer = typeof data.footer !== "undefined" ? new PayplugFooter(data.footer) : null;
    store.translations.multi_account = typeof data.multi_account !== "undefined" ? new PayplugMultiAccount(data.multi_account) : null;
}

export function populate_status(data) {
    store.translations.status = new PayplugStatus(data);
}

export function populate_subscribe(data) {
    store.translations.subscribe = new PayplugSubscribe(data);
}

function request_payment_method_permissions($payment_method) {

    store.settings.save.disabled = true;
    return new Promise((resolve, reject) => {
        $post(
            $payment_method,
            {"env": store.data.payplug_sandbox}
        )
            .then((response) => {
                resolve(response.data);
            })
            .catch(error => {
                reject(error);
                console.log(error);
            }).finally(function () {
            store.settings.save.disabled = false;
        })
    });

}

export function getDataE2e(optionsData, value) {
    return (value) ? optionsData + String(value).replace(value[0], value[0]?.toUpperCase()) : null
}

